<?php
declare(strict_types=1);
$modules=getcwd().'/backend/protected/modules';
spl_autoload_register(static function(string $class)use($modules):void{foreach(['matcherProfile'=>'matcher-user-profile','matcherPrivacy'=>'matcher-profile-privacy','matcherOnboarding'=>'matcher-onboarding'] as $ns=>$folder){$prefix='humhub\\modules\\'.$ns.'\\';if(str_starts_with($class,$prefix)){$path=$modules.'/'.$folder.'/'.str_replace('\\','/',substr($class,strlen($prefix))).'.php';if(is_file($path))require $path;}}});
use humhub\modules\matcherProfile\adapters\memory\InMemoryProfileRepository;
use humhub\modules\matcherProfile\adapters\memory\InMemoryProfileAccessPolicy;
use humhub\modules\matcherProfile\adapters\memory\InMemoryProfileWorkflow;
use humhub\modules\matcherProfile\adapters\memory\InMemoryQuestionRepository;
use humhub\modules\matcherProfile\adapters\memory\InMemoryProfileSourceRepository;
use humhub\modules\matcherProfile\application\ProfileService;
use humhub\modules\matcherProfile\application\ProfileSourceService;
use humhub\modules\matcherProfile\application\QuestionService;
use humhub\modules\matcherProfile\domain\ProfileScope;
use humhub\modules\matcherPrivacy\application\PrivacyService;
use humhub\modules\matcherPrivacy\application\ProfileReadPolicy;
use humhub\modules\matcherPrivacy\adapters\memory\InMemoryProfileRelations;
use humhub\modules\matcherOnboarding\adapters\memory\InMemoryOnboardingRepository;
use humhub\modules\matcherOnboarding\application\OnboardingService;
$repo=new InMemoryProfileRepository();$access=new InMemoryProfileAccessPolicy();$access->users=[1];$access->memberships=[7=>[1]];
$relations=new InMemoryProfileRelations();$relations->activeUsers=[1];$relations->memberships=$access->memberships;
$readPolicy=new ProfileReadPolicy($relations,$repo);$service=new ProfileService($repo,$access,null,null,$readPolicy);$privacy=new PrivacyService($service,$readPolicy,$repo);
$global=ProfileScope::global();$space=ProfileScope::event(7);$out=[];
$out['owner_empty']=$service->getProfile(1,1,$global);
$draft=$service->startDraft(1,1,$global);$draft=$service->updateDraft(1,1,$global,$draft['id'],$draft['draft_version'],[['key'=>'bio','value'=>"  合成内容\n保留空格🙂  ",'visibility'=>'private'],['key'=>'headline','value'=>'合成一句话','visibility'=>'authenticated'],['key'=>'contact_other','value'=>['label'=>'合成方式','value'=>'synthetic-only'],'visibility'=>'friends']]);
$out['draft_pending']=$service->getDraft(1,1,$global,$draft['id']);$out['owner_editing']=$service->getProfile(1,1,$global);
foreach(['owner','authenticated','friends'] as $perspective)$out['preview_pending_'.$perspective]=$privacy->preview(1,$global,$perspective,$draft['id']);
$service->confirmDraft(1,1,$global,$draft['id'],$draft['draft_version'],$draft['base_revision']);$out['draft_confirmed']=$service->getDraft(1,1,$global,$draft['id']);$out['owner_confirmed']=$service->getProfile(1,1,$global);
foreach(['owner','authenticated','friends'] as $perspective)$out['preview_confirmed_'.$perspective]=$privacy->preview(1,$global,$perspective);
$spaceDraft=$service->startDraft(1,1,$space);$spaceDraft=$service->updateDraft(1,1,$space,$spaceDraft['id'],$spaceDraft['draft_version'],[['key'=>'event_goal','value'=>['codes'=>['prototype']],'visibility'=>'authenticated']]);$out['draft_space']=$spaceDraft;$out['owner_space']=$service->getProfile(1,1,$space);$out['preview_space']=$privacy->preview(1,$space,'authenticated',$spaceDraft['id']);
$workflow=new InMemoryProfileWorkflow($repo,$service,$access);$qrepo=new InMemoryQuestionRepository();$srepo=new InMemoryOnboardingRepository();$workflow->participants=[$qrepo,$srepo];$questions=new QuestionService($qrepo,$workflow);$flow=new OnboardingService($srepo,$workflow,$questions);
$session=$flow->start(1,null);$out['progress_global']=$flow->getProgress(1,$session['id']);$spaceSession=$flow->start(1,7);$out['progress_space']=$flow->getProgress(1,$spaceSession['id']);
$sourceRepo=new InMemoryProfileSourceRepository();$sources=new ProfileSourceService($sourceRepo,$workflow,$access,static fn(string $kind)=>null);$out['capabilities_disabled']=$sources->capabilities(1);$out['sources_empty']=$sources->list(1);
echo json_encode($out,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);
